#!/bin/sh
# Window title bars (issues #15, #33): the Labwc WorkSuite themes exist, are installed, have every button image Labwc
# looks for (generated by services/session/themes/make-buttons.py, in step), and rc.xml lays the buttons out like
# Windows 11 (Minimize, Maximize/Restore, Close at the top right) with server-side decorations.
set -u
ROOT=$(cd "$(dirname "$0")/../.." && pwd)
T=$ROOT/services/session/themes
RC=$ROOT/services/session/labwc/rc.xml
fail=0
ok() { echo "ok - $1"; }
bad() { echo "not ok - $1"; fail=1; }

python3 -I "$T/make-buttons.py" --check && ok "button images in step with make-buttons.py" || bad "button images in step with make-buttons.py"
for th in WorkSuite WorkSuite-Light; do
  f=$T/$th/labwc/themerc
  [ -f "$f" ] && ok "$th themerc" || bad "$th themerc"
  for k in window.button.width window.button.height window.active.title.bg.color window.inactive.title.bg.color \
           window.active.label.text.color window.inactive.label.text.color window.active.border.color; do
    grep -q "^$k: " "$f" || bad "$th: $k"
  done
  grep -q '^window.button.width: 46$' "$f" && grep -q '^window.button.height: 32$' "$f" && ok "$th: 46 x 32 px buttons" || bad "$th: 46 x 32 px buttons"
  for b in iconify max max_toggled close; do
    for s in active inactive; do
      [ -f "$T/$th/labwc/$b-$s.svg" ] && [ -f "$T/$th/labwc/${b}_hover-$s.svg" ] || bad "$th: $b $s images"
    done
  done
  grep -q 'fill="#C42B1C"' "$T/$th/labwc/close_hover-active.svg" && ok "$th: red Close on hover" || bad "$th: red Close on hover"
  grep -q "^services/session/themes/$th usr/share/themes/\$" "$ROOT/packaging/debian/worksuite-session.install" && ok "$th installed" || bad "$th installed"
done
python3 -I - "$RC" <<'PY' && ok "rc.xml: valid, SSD, WorkSuite theme, icon:iconify,max,close, rounded" || bad "rc.xml: valid, SSD, WorkSuite theme, icon:iconify,max,close, rounded"
import sys, xml.etree.ElementTree as E
r = E.parse(sys.argv[1]).getroot()
assert r.findtext('core/decoration') == 'server'
assert r.findtext('theme/name') == 'WorkSuite'
assert r.findtext('theme/titlebar/layout').replace(' ', '') == 'icon:iconify,max,close'
assert int(r.findtext('theme/cornerRadius')) == 8
assert r.find('mouse') is None  # Labwc's default bindings: drag to move, edges to resize, double-click to maximize
keys = {k.get('key') for k in r.iter('keybind')}
assert {'W-Up', 'W-Down', 'W-Left', 'W-Right', 'A-F4'} <= keys
PY
exit $fail
